<?php require __DIR__.'/../includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$booking=intval($_POST['booking']);if(isset($_POST['worker'])){$worker=intval($_POST['worker']);$pdo->prepare("UPDATE bookings SET worker_id=?,status='Worker Assigned' WHERE id=?")->execute([$worker,$booking]);$pdo->prepare("INSERT INTO booking_status_history(booking_id,status) VALUES(?,'Worker Assigned')")->execute([$booking]);}if(isset($_POST['status'])&&in_array($_POST['status'],['Pending','Accepted','Worker Assigned','On the Way','Work Started','Estimate Awaiting Approval','Work In Progress','Completed','Cancelled','Rejected'],true)){$pdo->prepare("UPDATE bookings SET status=? WHERE id=?")->execute([$_POST['status'],$booking]);$pdo->prepare("INSERT INTO booking_status_history(booking_id,status) VALUES(?,?)")->execute([$booking,$_POST['status']]);}flash('Booking updated.');redirect('bookings.php');}$bookings=$pdo->query("SELECT b.*,c.name customer,s.name service,w.name worker FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN services s ON s.id=b.service_id LEFT JOIN workers w ON w.id=b.worker_id ORDER BY b.created_at DESC")->fetchAll();$workers=$pdo->query("SELECT id,name,category FROM workers WHERE status='approved'")->fetchAll();$pageTitle='Bookings';require __DIR__.'/../includes/header.php';?><div class="dashboard"><aside class="side-nav"><a href="index.php">Overview</a><a href="workers.php">Workers</a><a class="active" href="bookings.php">Bookings</a><a href="services.php">Services & pricing</a></aside><main class="dashboard-main"><h2>Booking management</h2><table><thead><tr><th>ID</th><th>Customer / Service</th><th>Date</th><th>Worker</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['customer'])?><br><small><?=e($b['service'])?></small></td><td><?=e($b['booking_date'])?></td><td><?=e($b['worker']??'Not assigned')?></td><td><?=e($b['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="booking" value="<?=e($b['id'])?>"><select name="worker"><option value="0">Choose worker</option><?php foreach($workers as $w):?><option value="<?=e($w['id'])?>"><?=e($w['name'])?> (<?=e($w['category'])?>)</option><?php endforeach?></select><select name="status"><option><?=e($b['status'])?></option><option>Accepted</option><option>Work In Progress</option><option>Completed</option><option>Cancelled</option></select><button class="btn btn-primary">Update</button></form></td></tr><?php endforeach;if(!$bookings):?><tr><td colspan="6">No bookings yet.</td></tr><?php endif?></tbody></table></main></div><?php require __DIR__.'/../includes/footer.php';?>